import {esc,safeUrl} from '../../ui/format.js';
import {intro,references,decisions,commercial,generic} from './references.js';
const link=(url,label)=>`<a href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
export function bibliographyView(){return `<section class="page-intro"><div><div class="eyebrow">DOCUMENTAȚIE · PROVENIENȚĂ · LIMITE</div><h1>Bibliografie & surse</h1><p>Ce provine dintr-o fișă tehnică, ce este referință metodologică și ce este ipoteză de model.</p></div><a class="primary bibliography-download" href="bibliografie.md" download>Descarcă bibliografia</a></section><section class="panel"><h2>Proveniență explicită</h2><p>${esc(intro)}</p><p><b>${commercial.length} fișe comerciale · ${references.length} referințe metodologice / MBSE · ${generic.length} șabloane generice.</b></p><p>Sursele comerciale au fost consemnate la 9 octombrie 2026. Bibliografia reproduce sursele și valorile din catalog, fără a pretinde o nouă verificare a tuturor fișelor astăzi. Site-urile producătorilor și configurațiile se pot modifica; nu sunt arhivate copii integrale ale fișelor.</p><nav class="bibliography-nav" aria-label="Secțiuni bibliografie"><a href="#bibliography-method">Metodologie</a><a href="#bibliography-assumptions">Ipoteze și calcul</a><a href="#bibliography-catalog">Fișe comerciale</a><a href="#bibliography-generic">Șabloane generice</a></nav></section><section id="bibliography-method"><h2>Simulare, eficientizare și MBSE</h2>${references.map(r=>`<article class="panel"><span class="badge">${esc(r.id)} · ${esc(r.status)}</span><h3>${link(r.url,r.title)}</h3><p class="muted">${esc(r.publication)}</p><p><b>Legătura cu aplicația:</b> ${esc(r.use)}</p><p><b>Limită:</b> ${esc(r.limit)}</p></article>`).join('')}</section><section class="panel" id="bibliography-assumptions"><h2>Trasabilitate între metodă și implementare</h2>${decisions.map(([name,text,code])=>`<h3>${esc(name)}</h3><p>${esc(text)}</p><p class="small muted">${esc(code)}</p>`).join('')}<p>Verificarea locală include calcule de referință, conservarea pieselor/materialelor, competiția pentru resurse, compatibilitatea porturilor și consistența API-ului de simulare. Acestea sunt teste ale aplicației, nu studii independente de validare industrială.</p></section><section id="bibliography-catalog"><h2>Toate fișele comerciale din bibliotecă</h2><p>Valorile de mai jos sunt referințele originale; instanțele din model pot avea valori editate. Ele nu stabilesc automat ciclul, costul, rebutul, MTBF sau MTTR.</p>${commercial.map((t,i)=>`<article class="panel"><span class="badge">C${i+1} · verificare consemnată ${esc(t.checked)}</span><h3>${link(t.source,t.name)}</h3><p>${esc(t.configuration)}</p><ul>${t.specs.map(s=>`<li>${esc(s.name)}: <b>${s.referenceValue} ${esc(s.unit)}</b></li>`).join('')}</ul></article>`).join('')}</section><section class="panel" id="bibliography-generic"><h2>Toate șabloanele generice</h2><p>Fără fișe comerciale atribuite: sunt șabloane proprii, editabile. Valorile inițiale sunt configurații/ipoteze; necesită calibrare. Lista de mai jos explică de ce aceste elemente nu au citări de producător.</p><ul>${generic.map(t=>`<li>${esc(t.name)} — ${esc(t.category)}</li>`).join('')}</ul></section>`}
